import {readGitMarkerVersions} from './git-conflict-markers.js';
const api=async(request,command,params)=>{const response=await request('/api/source-control/'+command,{method:'POST',body:JSON.stringify(params)}),data=await response.json();if(!response.ok||data.error)throw Error(data.error||'JSON 충돌 요청에 실패했어요.');return data;};
export async function readGitAssetMerge(request,path){const snapshot=await api(request,'conflict',{path,includeData:true,includeStages:false}),versions=readGitMarkerVersions(snapshot.workingText,{baseText:snapshot.base??undefined});return{...versions,path,indexRevision:snapshot.indexRevision,workingSHA256:snapshot.workingSHA256};}
export async function applyGitAssetMerge(request,snapshot,resolutions,{dryRun=false,includeData=true,reviewedData,guard=()=>{}}={}){let expectedCandidateSHA256;if(reviewedData!==undefined){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(reviewedData)));expectedCandidateSHA256=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');}guard();const result=await api(request,'resolve',{path:snapshot.path,expectedIndexRevision:snapshot.indexRevision,expectedWorkingSHA256:snapshot.workingSHA256,resolutions:structuredClone(resolutions),dryRun,includeData,expectedCandidateSHA256});if(!dryRun&&!result.applied)throw Error('선택하지 않은 JSON 충돌이 남아 있어요.');return result;}
